function serveSite(request, path) {
  const file = path === "/" ? "index.html" : path.slice(1);
  const extension = file.split(".").at(-1).toLowerCase();
  const content = file === "chat.js" ? siteChat : Object.hasOwn(siteFiles, file) ? siteFiles[file] : undefined;

  if (content !== undefined) {
    return new Response(request.method === "HEAD" ? null : content, {
      headers: { ...siteHeaders, "Content-Type": types[extension] }
    });
  }

  if (file === "images/Logos%20MC%20-Pink%20RGB-59.png") {
    return new Response(null, {
      status: 302,
      headers: { ...siteHeaders, Location: "https://raw.githubusercontent.com/xserbia/menudocuenta/85724847ec155fb56f8cdcab2f8dc5de41bceb87/images/Logos%20MC%20-Pink%20RGB-59.png" }
    });
  }

  if (/^(?:images|fonts)\/[^?#\\]+$/.test(file) &&
      Object.hasOwn(types, extension) && !["html", "css", "js"].includes(extension)) {
    const asset = new URL(file, publicAssets);
    if (asset.href.startsWith(publicAssets)) {
      return new Response(null, { status: 302, headers: { ...siteHeaders, Location: asset.href } });
    }
  }

  return new Response(request.method === "HEAD" ? null : "Página no disponible.", {
    status: 404, headers: siteHeaders
  });
}

export default {
  async fetch(request, env) {
    if (!env.PREVIEW_PASSWORD) {
      return new Response("Configura el secreto PREVIEW_PASSWORD para habilitar la prueba.", { status: 503, headers });
    }
    const required = "Basic " + btoa("emc:" + env.PREVIEW_PASSWORD);
    if (request.headers.get("Authorization") !== required) {
      return new Response("Acceso a la prueba de EMC", {
        status: 401,
        headers: { ...headers, "WWW-Authenticate": 'Basic realm="EMC Chatbot Preview", charset="UTF-8"' }
      });
    }

    const path = new URL(request.url).pathname;
    if (request.method === "POST" && path === "/api/chat") return respond(request, env);
    if (request.method === "GET" || request.method === "HEAD") return serveSite(request, path);
    return json({ error: "Ruta no disponible." }, 404);
  }
};

